class LoginScreen extends StatefulWidget { const LoginScreen({Key? key}) : super(key: key); @override State<LoginScreen> createState()=>_LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen>{
 final _usernameController=TextEditingController(); final _passwordController=TextEditingController(); String _selectedRole='STUDENT';
 void _login() async {final auth=Provider.of<AuthProvider>(context,listen:false);final username=_usernameController.text.trim().isNotEmpty?_usernameController.text.trim():_selectedRole.toLowerCase();final success=await auth.login(username,_passwordController.text);if(!mounted)return;if(success&&auth.currentUser!=null){switch(auth.currentUser!.role.toUpperCase()){case 'ADMIN':Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const AdminOversightScreen()));break;case 'VENDOR':Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const VendorDashboardScreen()));break;default:Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const StudentDashboardScreen()));}}else{ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(auth.errorMessage??'Login failed. Please check credentials.')));}}
